return UnityEngine.Object.FindObjectsByType<UnityEngine.SkinnedMeshRenderer>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Hero_")).Take(4).Select(r=>new {r.name,prefab=UnityEditor.PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject),outer=UnityEditor.PrefabUtility.GetOutermostPrefabInstanceRoot(r.gameObject)?.name,mesh=UnityEditor.AssetDatabase.GetAssetPath(r.sharedMesh),materials=r.sharedMaterials.Select(m=>new {m.name,shader=m.shader.name,path=UnityEditor.AssetDatabase.GetAssetPath(m)}).ToArray()}).ToArray();
